/** @responsibility Defines the stable orientation, split-direction, drop-region, and dock vocabulary of the app-shell layout model. */

/** Axes along which a split node lays out its children. */
const SplitOrientation = Object.freeze({
  Horizontal: "horizontal",
  Vertical: "vertical",
} as const)

/** A supported axis for a split node's children. */
type SplitOrientation = (typeof SplitOrientation)[keyof typeof SplitOrientation]

/** Directions in which an existing pane can be split. */
const PaneSplitDirection = Object.freeze({
  Up: "up",
  Down: "down",
  Left: "left",
  Right: "right",
} as const)

/** A supported direction for splitting an existing pane. */
type PaneSplitDirection =
  (typeof PaneSplitDirection)[keyof typeof PaneSplitDirection]

/**
 * Regions of a pane that can accept a dropped pane or view. Reserved
 * vocabulary for the drag-and-drop layer; unused by resize-only layouts.
 */
const PaneDropRegion = Object.freeze({
  Center: "center",
  Top: "top",
  Right: "right",
  Bottom: "bottom",
  Left: "left",
} as const)

/** A supported drop region within a pane. */
type PaneDropRegion = (typeof PaneDropRegion)[keyof typeof PaneDropRegion]

/** Fixed dock slots surrounding the recursive workspace. */
const AppShellDockSide = Object.freeze({
  Left: "left",
  Right: "right",
  Bottom: "bottom",
} as const)

/** A supported dock slot around the workspace. */
type AppShellDockSide = (typeof AppShellDockSide)[keyof typeof AppShellDockSide]

/**
 * Resolves the split orientation produced by splitting along a direction.
 *
 * @param direction - The requested split direction.
 * @returns The orientation of the split node that hosts the two panes.
 */
function splitDirectionToOrientation(
  direction: PaneSplitDirection,
): SplitOrientation {
  return direction === PaneSplitDirection.Left ||
    direction === PaneSplitDirection.Right
    ? SplitOrientation.Horizontal
    : SplitOrientation.Vertical
}

/**
 * Determines whether a split direction inserts after the reference pane.
 *
 * @param direction - The requested split direction.
 * @returns Whether the new pane lands after (right of / below) the reference.
 */
function splitDirectionIsAfter(direction: PaneSplitDirection): boolean {
  return (
    direction === PaneSplitDirection.Right ||
    direction === PaneSplitDirection.Down
  )
}

export {
  AppShellDockSide,
  PaneDropRegion,
  PaneSplitDirection,
  SplitOrientation,
  splitDirectionIsAfter,
  splitDirectionToOrientation,
}

/** @responsibility Defines the serializable, JSON-safe layout document rendered by the AppShell composite. */

import type { AppShellDockSide, SplitOrientation } from "./layout-options"

/** Current schema version written by `createAppShellLayout`. */
const APP_SHELL_LAYOUT_VERSION = 1

/**
 * Stable, opaque identity for one layout node. Never derived from position;
 * ids survive splits, closes, and future drag-and-drop moves. The consuming
 * application is responsible for keeping ids unique within one document.
 */
type LayoutNodeId = string

/**
 * Stable key the consuming application resolves to renderable pane content.
 * The layout model never stores React elements; it stores these keys only.
 */
type PaneViewId = string

/** A leaf of the workspace tree hosting an ordered list of views. */
interface PaneNode {
  readonly type: "pane"
  readonly id: LayoutNodeId
  /**
   * Share of the parent split's main axis. Siblings sum to 1 after
   * normalization. Unitless and display-independent; ignored on the root.
   */
  readonly weight: number
  /**
   * Ordered views hosted by this pane. Resize-only layouts render the active
   * view; a future tab strip renders the full list without a schema change.
   */
  readonly views: readonly PaneViewId[]
  /** The view currently presented by this pane. */
  readonly activeViewId?: PaneViewId
}

/** An n-ary interior node laying out children along one explicit axis. */
interface SplitNode {
  readonly type: "split"
  readonly id: LayoutNodeId
  /**
   * Share of the parent split's main axis. Siblings sum to 1 after
   * normalization. Unitless and display-independent; ignored on the root.
   */
  readonly weight: number
  /** The axis along which children are laid out. Never inferred from depth. */
  readonly orientation: SplitOrientation
  /** Ordered children. Normalized splits always hold two or more. */
  readonly children: readonly LayoutNode[]
}

/** Any node of the recursive workspace tree. */
type LayoutNode = PaneNode | SplitNode

/** The recursive center region of the shell plus its out-of-tree pointers. */
interface WorkspaceLayout {
  /** The tree root. A lone pane is a legal root for single-pane layouts. */
  readonly root: LayoutNode
  /** The pane that owns focus-routed commands. References an existing pane. */
  readonly activePaneId: LayoutNodeId
  /**
   * Most-recently-active pane ids, most recent first. Determines where focus
   * lands after the active pane closes.
   */
  readonly recentPaneIds: readonly LayoutNodeId[]
  /**
   * A pane temporarily presented over the whole workspace. Rendering-only;
   * maximizing never restructures the tree.
   */
  readonly maximizedPaneId?: LayoutNodeId
}

/** Visibility and extent of one fixed dock slot. */
interface AppShellDockState {
  /** Whether the dock is currently presented. */
  readonly open: boolean
  /**
   * Extent along the dock's resize axis in CSS pixels. Retained while the
   * dock is closed so reopening restores the previous extent.
   */
  readonly size: number
}

/** The complete serializable layout document for one AppShell. */
interface AppShellLayout {
  /** Schema version. Consumers migrate or discard on mismatch. */
  readonly version: typeof APP_SHELL_LAYOUT_VERSION
  /** Fixed, pixel-sized dock slots outside the recursive tree. */
  readonly docks: Readonly<Record<AppShellDockSide, AppShellDockState>>
  /** The recursive, weight-sized workspace. */
  readonly workspace: WorkspaceLayout
}

export {
  APP_SHELL_LAYOUT_VERSION,
  type AppShellDockState,
  type AppShellLayout,
  type LayoutNode,
  type LayoutNodeId,
  type PaneNode,
  type PaneViewId,
  type SplitNode,
  type WorkspaceLayout,
}

/** @responsibility Restores the structural invariants of a layout document after any mutation or deserialization. */

import type {
  AppShellDockState,
  AppShellLayout,
  LayoutNode,
  LayoutNodeId,
  PaneNode,
  SplitNode,
  WorkspaceLayout,
} from "./layout-types"

/** Tolerance used when checking that sibling weights already sum to one. */
const WEIGHT_SUM_TOLERANCE = 0.000001

/**
 * Rounds a weight to a stable precision so repeated normalization does not
 * accumulate floating-point drift.
 *
 * @param weight - The raw weight value.
 * @returns The weight rounded to six decimal places.
 */
function formatWeight(weight: number): number {
  return parseFloat(weight.toFixed(6))
}

/**
 * Rescales sibling weights so they always add up to exactly 1.
 *
 * A weight of 0 is allowed — that is simply a fully collapsed pane. Only
 * broken input (negative numbers, NaN, or a total of 0) is replaced with an
 * even share for everyone.
 *
 * @example
 * ```txt
 * [2, 1, 1]      → [0.5, 0.25, 0.25]   scaled so the total is 1
 * [0, 0.4, 0.6]  → [0, 0.4, 0.6]       already fine, zero stays
 * [-2, NaN]      → [0.5, 0.5]          broken input → even split
 * ```
 *
 * @param weights - The proposed sibling weights.
 * @returns Sibling weights that are non-negative and sum to one.
 */
function normalizeWeights(weights: readonly number[]): number[] {
  const invalid = weights.some(
    (weight) => !Number.isFinite(weight) || weight < 0,
  )
  const total = weights.reduce((sum, weight) => sum + weight, 0)

  if (invalid || total <= 0) {
    return weights.map(() => formatWeight(1 / weights.length))
  }

  if (Math.abs(total - 1) <= WEIGHT_SUM_TOLERANCE) {
    return [...weights]
  }

  return weights.map((weight) => formatWeight(weight / total))
}

/**
 * Cleans up one subtree, working from the leaves upward. Two shapes get
 * repaired, and neither repair changes what the user sees on screen:
 *
 * 1. A split nested inside another split that points the same way is
 *    merged into its parent (the child weights are scaled so sizes stay
 *    identical):
 *
 * ```txt
 *    before                         after
 *    H ─────────────────            H ─────────────────
 *    ├─ pane A (0.5)               ├─ pane A (0.5)
 *    └─ H (0.5)              →     ├─ pane B (0.25)
 *       ├─ pane B (0.5)            └─ pane C (0.25)
 *       └─ pane C (0.5)
 * ```
 *
 * 2. A split left with a single child disappears — the child takes its
 *    place (and its weight):
 *
 * ```txt
 *    H ─────────────────
 *    ├─ pane A (0.5)               H ─────────────────
 *    └─ V (0.5)              →     ├─ pane A (0.5)
 *       └─ pane B (1)              └─ pane B (0.5)
 * ```
 *
 * Sibling weights are rescaled at each level so they sum to 1.
 *
 * @param node - The subtree root to normalize.
 * @returns The normalized subtree, or null when the subtree holds no panes.
 */
function normalizeNode(node: LayoutNode): LayoutNode | null {
  if (node.type === "pane") {
    return node
  }

  const children: LayoutNode[] = []

  for (const child of node.children) {
    const normalized = normalizeNode(child)

    if (!normalized) continue

    if (
      normalized.type === "split" &&
      normalized.orientation === node.orientation
    ) {
      // A split inside a split pointing the same way looks exactly like one
      // flat row of siblings, so we lift its children up a level. Scaling
      // each lifted weight by the old wrapper's weight keeps every pane at
      // the same on-screen size.
      for (const grandchild of normalized.children) {
        children.push({
          ...grandchild,
          weight: formatWeight(grandchild.weight * normalized.weight),
        })
      }
    } else {
      children.push(normalized)
    }
  }

  if (children.length === 0) {
    return null
  }

  if (children.length === 1) {
    const child = children[0]
    return child.weight === node.weight
      ? child
      : { ...child, weight: node.weight }
  }

  const weights = normalizeWeights(children.map((child) => child.weight))
  const normalizedChildren = children.map((child, index) =>
    child.weight === weights[index]
      ? child
      : { ...child, weight: weights[index] },
  )

  const unchanged =
    normalizedChildren.length === node.children.length &&
    normalizedChildren.every((child, index) => child === node.children[index])

  return unchanged ? node : { ...node, children: normalizedChildren }
}

/**
 * Collects every pane in traversal order.
 *
 * @param node - The subtree root to walk.
 * @returns All pane nodes in depth-first, start-to-end order.
 */
function collectPanes(node: LayoutNode): PaneNode[] {
  if (node.type === "pane") {
    return [node]
  }

  return node.children.flatMap(collectPanes)
}

/**
 * Finds a node by id.
 *
 * @param node - The subtree root to search.
 * @param id - The node id to find.
 * @returns The matching node, or undefined when absent.
 */
function findNode(node: LayoutNode, id: LayoutNodeId): LayoutNode | undefined {
  if (node.id === id) {
    return node
  }

  if (node.type === "split") {
    for (const child of node.children) {
      const match = findNode(child, id)
      if (match) return match
    }
  }

  return undefined
}

/**
 * Repairs a whole workspace: cleans the tree (see `normalizeNode`) and then
 * fixes the three bookkeeping pointers so none of them names a pane that no
 * longer exists — the active pane falls back to the most recently used
 * surviving pane, the recently-used list drops dead ids and duplicates, and
 * a stale maximize pointer is cleared.
 *
 * @param workspace - The workspace layout to normalize.
 * @returns An equivalent workspace with every rule restored.
 */
function normalizeWorkspaceLayout(workspace: WorkspaceLayout): WorkspaceLayout {
  // A document with no panes at all (for example an empty split from a bad
  // save) cannot render or accept operations, so it becomes one empty pane.
  const root: LayoutNode = normalizeNode(workspace.root) ?? {
    type: "pane",
    id: workspace.activePaneId || "pane-1",
    weight: 1,
    views: [],
  }
  const panes = collectPanes(root)
  const paneIds = new Set(panes.map((pane) => pane.id))

  const recentPaneIds = workspace.recentPaneIds.filter(
    (id, index, ids) => paneIds.has(id) && ids.indexOf(id) === index,
  )

  const activePaneId = paneIds.has(workspace.activePaneId)
    ? workspace.activePaneId
    : (recentPaneIds[0] ?? panes[0]?.id ?? workspace.activePaneId)

  if (paneIds.has(activePaneId) && activePaneId !== recentPaneIds[0]) {
    const remaining = recentPaneIds.filter((id) => id !== activePaneId)
    recentPaneIds.length = 0
    recentPaneIds.push(activePaneId, ...remaining)
  }

  const maximizedPaneId =
    workspace.maximizedPaneId !== undefined &&
    paneIds.has(workspace.maximizedPaneId)
      ? workspace.maximizedPaneId
      : undefined

  const unchanged =
    root === workspace.root &&
    activePaneId === workspace.activePaneId &&
    maximizedPaneId === workspace.maximizedPaneId &&
    recentPaneIds.length === workspace.recentPaneIds.length &&
    recentPaneIds.every((id, index) => id === workspace.recentPaneIds[index])

  if (unchanged) {
    return workspace
  }

  return {
    root,
    activePaneId,
    recentPaneIds,
    ...(maximizedPaneId !== undefined ? { maximizedPaneId } : {}),
  }
}

/**
 * Repairs one dock entry: `open` becomes a real boolean and `size` becomes
 * a whole, non-negative number of pixels (broken sizes fall back to 0; the
 * dock component clamps to its real minimum when rendering).
 *
 * @param dock - The dock state to repair.
 * @returns The repaired dock state, or the same object when already clean.
 */
function normalizeDockState(dock: AppShellDockState): AppShellDockState {
  const open = dock.open === true
  const size =
    Number.isFinite(dock.size) && dock.size >= 0 ? Math.round(dock.size) : 0

  return open === dock.open && size === dock.size ? dock : { open, size }
}

/**
 * Repairs a complete layout document — the workspace tree, its pointers,
 * and the dock entries. Safe to call as often as needed: running it on an
 * already clean document returns the very same object.
 *
 * @param layout - The layout document to normalize.
 * @returns An equivalent document with every rule restored.
 */
function normalizeAppShellLayout(layout: AppShellLayout): AppShellLayout {
  const workspace = normalizeWorkspaceLayout(layout.workspace)

  let docks = layout.docks

  for (const [side, dock] of Object.entries(layout.docks)) {
    const normalized = normalizeDockState(dock)

    if (normalized !== dock) {
      docks = { ...docks, [side]: normalized }
    }
  }

  return workspace === layout.workspace && docks === layout.docks
    ? layout
    : { ...layout, workspace, docks }
}

export {
  collectPanes,
  findNode,
  formatWeight,
  normalizeAppShellLayout,
  normalizeWeights,
  normalizeWorkspaceLayout,
}

/** @responsibility Provides the pure operations that evolve a layout document; every structural edit re-normalizes. */

import {
  AppShellDockSide,
  PaneSplitDirection,
  SplitOrientation,
  splitDirectionIsAfter,
  splitDirectionToOrientation,
} from "./layout-options"
import {
  collectPanes,
  findNode,
  formatWeight,
  normalizeAppShellLayout,
} from "./layout-normalize"
import {
  APP_SHELL_LAYOUT_VERSION,
  type AppShellLayout,
  type LayoutNode,
  type LayoutNodeId,
  type PaneNode,
  type PaneViewId,
  type SplitNode,
  type WorkspaceLayout,
} from "./layout-types"

/** Values accepted for creating one workspace pane. */
interface CreatePaneOptions {
  /** Unique id for the pane. */
  id: LayoutNodeId
  /**
   * Share of the parent split's main axis.
   * @defaultValue 1
   */
  weight?: number
  /**
   * Ordered views hosted by the pane.
   * @defaultValue []
   */
  views?: readonly PaneViewId[]
  /** The view the pane presents. Defaults to the first provided view. */
  activeViewId?: PaneViewId
}

/**
 * Creates one pane node.
 *
 * @param options - The pane id, optional weight, and hosted views.
 * @returns A pane node ready for insertion into a workspace tree.
 */
function createPaneNode(options: CreatePaneOptions): PaneNode {
  const views = options.views ?? []
  const activeViewId = options.activeViewId ?? views[0]

  return {
    type: "pane",
    id: options.id,
    weight: options.weight ?? 1,
    views,
    ...(activeViewId !== undefined ? { activeViewId } : {}),
  }
}

/** Values accepted for creating a default layout document. */
interface CreateAppShellLayoutOptions {
  /**
   * Id of the initial pane.
   * @defaultValue "pane-1"
   */
  initialPaneId?: LayoutNodeId
  /**
   * Views hosted by the initial pane.
   * @defaultValue []
   */
  views?: readonly PaneViewId[]
  /**
   * Initial pixel sizes per dock side.
   * @defaultValue left/right 288, bottom 240
   */
  dockSizes?: Partial<Record<AppShellDockSide, number>>
  /**
   * Dock sides that start open.
   * @defaultValue [AppShellDockSide.Left]
   */
  openDocks?: readonly AppShellDockSide[]
}

/**
 * Creates a minimal, normalized layout document with a single pane.
 *
 * @param options - Initial pane identity, views, and dock configuration.
 * @returns A complete layout document ready to render.
 */
function createAppShellLayout(
  options: CreateAppShellLayoutOptions = {},
): AppShellLayout {
  const initialPaneId = options.initialPaneId ?? "pane-1"
  const openDocks = options.openDocks ?? [AppShellDockSide.Left]

  const dockState = (side: AppShellDockSide, defaultSize: number) => ({
    open: openDocks.includes(side),
    size: options.dockSizes?.[side] ?? defaultSize,
  })

  return {
    version: APP_SHELL_LAYOUT_VERSION,
    docks: {
      [AppShellDockSide.Left]: dockState(AppShellDockSide.Left, 288),
      [AppShellDockSide.Right]: dockState(AppShellDockSide.Right, 288),
      [AppShellDockSide.Bottom]: dockState(AppShellDockSide.Bottom, 240),
    },
    workspace: {
      root: createPaneNode({ id: initialPaneId, views: options.views }),
      activePaneId: initialPaneId,
      recentPaneIds: [initialPaneId],
    },
  }
}

/**
 * Puts a new node next to an existing one. There are only two cases, and
 * they are the same rule Zed and VS Code use:
 *
 * Case 1 — the new node goes the same way the parent already flows.
 * It slides in as one more sibling, and the target shares its space:
 *
 * ```txt
 *   ┌─────┬─────┐   insert N        ┌──┬──┬─────┐
 *   │  A  │  B  │   right of A  →   │A │N │  B  │
 *   └─────┴─────┘                   └──┴──┴─────┘
 *    A ½    B ½                     A ¼  N ¼  B ½
 * ```
 *
 * Case 2 — the new node goes across the parent's flow.
 * The target gets wrapped in a small new split holding both:
 *
 * ```txt
 *   ┌─────┬─────┐   insert N        ┌─────┬─────┐
 *   │  A  │  B  │   below A     →   │  A  │     │
 *   └─────┴─────┘                   ├─────┤  B  │
 *                                   │  N  │     │
 *                                   └─────┴─────┘
 * ```
 *
 * @param root - The tree root.
 * @param targetId - The node the insertion is relative to.
 * @param node - The node to insert.
 * @param direction - Where the inserted node lands relative to the target.
 * @param wrapSplitId - Id used when a new split node must be created.
 * @returns The new root, or the original root when the target is absent.
 */
function insertRelativeTo(
  root: LayoutNode,
  targetId: LayoutNodeId,
  node: LayoutNode,
  direction: PaneSplitDirection,
  wrapSplitId: LayoutNodeId,
): LayoutNode {
  const orientation = splitDirectionToOrientation(direction)
  const after = splitDirectionIsAfter(direction)

  /**
   * Wraps the matched target in a new split sharing the target's weight.
   *
   * @param target - The node being split.
   * @returns The replacement split node.
   */
  const wrapTarget = (target: LayoutNode): SplitNode => {
    const halves: LayoutNode[] = [
      { ...target, weight: 0.5 },
      { ...node, weight: 0.5 },
    ]

    return {
      type: "split",
      id: wrapSplitId,
      weight: target.weight,
      orientation,
      children: after ? halves : [halves[1], halves[0]],
    }
  }

  if (root.id === targetId) {
    return wrapTarget(root)
  }

  /**
   * Rebuilds one subtree with the insertion applied.
   *
   * @param current - The subtree root being visited.
   * @returns The rebuilt subtree, or the same reference when untouched.
   */
  const visit = (current: LayoutNode): LayoutNode => {
    if (current.type === "pane") {
      return current
    }

    const targetIndex = current.children.findIndex(
      (child) => child.id === targetId,
    )

    if (targetIndex !== -1) {
      const target = current.children[targetIndex]

      if (current.orientation === orientation) {
        // Case 1: same direction. The new node becomes a sibling, and the
        // two of them split the target's old space in half — nobody else
        // moves.
        const half = formatWeight(target.weight / 2)
        const children = [...current.children]
        children[targetIndex] = { ...target, weight: half }
        children.splice(after ? targetIndex + 1 : targetIndex, 0, {
          ...node,
          weight: half,
        })

        return { ...current, children }
      }

      const children = [...current.children]
      children[targetIndex] = wrapTarget(target)

      return { ...current, children }
    }

    const children = current.children.map(visit)
    const unchanged = children.every(
      (child, index) => child === current.children[index],
    )

    return unchanged ? current : { ...current, children }
  }

  return visit(root)
}

/**
 * Removes a node from the tree. The freed space goes to the neighbor on the
 * left (or the right, when the removed node was first) — not spread across
 * everyone — so closing a pane exactly undoes the split that created it:
 *
 * ```txt
 *   ┌──┬──┬─────┐    remove N     ┌─────┬─────┐
 *   │A │N │  B  │        →        │  A  │  B  │
 *   └──┴──┴─────┘                 └─────┴─────┘
 *   A ¼  N ¼  B ½                  A ½    B ½
 * ```
 *
 * @param root - The tree root.
 * @param id - The id of the node to remove.
 * @returns The remaining root (null when the tree empties) and the removed
 * node (null when the id is absent).
 */
function removeNode(
  root: LayoutNode,
  id: LayoutNodeId,
): { root: LayoutNode | null; removed: LayoutNode | null } {
  if (root.id === id) {
    return { root: null, removed: root }
  }

  let removed: LayoutNode | null = null

  /**
   * Rebuilds one subtree with the removal applied.
   *
   * @param current - The subtree root being visited.
   * @returns The rebuilt subtree, or the same reference when untouched.
   */
  const visit = (current: LayoutNode): LayoutNode => {
    if (current.type === "pane" || removed) {
      return current
    }

    const index = current.children.findIndex((child) => child.id === id)

    if (index !== -1) {
      removed = current.children[index]
      const children = current.children.filter((_, at) => at !== index)
      const heirIndex = Math.max(0, index - 1)

      if (children[heirIndex]) {
        children[heirIndex] = {
          ...children[heirIndex],
          weight: formatWeight(children[heirIndex].weight + removed.weight),
        }
      }

      return { ...current, children }
    }

    const children = current.children.map(visit)
    const unchanged = children.every(
      (child, at) => child === current.children[at],
    )

    return unchanged ? current : { ...current, children }
  }

  const nextRoot = visit(root)

  return { root: removed ? nextRoot : root, removed }
}

/**
 * Moves a pane id to the front of the recently-used list.
 *
 * @example
 * ```txt
 * (["a", "b", "c"], "b") → ["b", "a", "c"]
 * ```
 *
 * @param recentPaneIds - The current recently-used list, newest first.
 * @param paneId - The pane id to move to the front.
 * @returns The list with the pane first and duplicates removed.
 */
function promoteRecentPane(
  recentPaneIds: readonly LayoutNodeId[],
  paneId: LayoutNodeId,
): LayoutNodeId[] {
  return [paneId, ...recentPaneIds.filter((id) => id !== paneId)]
}

/** Values accepted when splitting a pane. */
interface SplitPaneOptions {
  /** The pane being split. */
  paneId: LayoutNodeId
  /** Where the new pane lands relative to the split pane. */
  direction: PaneSplitDirection
  /** Unique id for the new pane. */
  newPaneId: LayoutNodeId
  /**
   * Views hosted by the new pane.
   * @defaultValue []
   */
  views?: readonly PaneViewId[]
  /** The view the new pane presents. Defaults to the first provided view. */
  activeViewId?: PaneViewId
  /**
   * Id used when a new split node must wrap the target.
   * @defaultValue "split:" + newPaneId
   */
  newSplitId?: LayoutNodeId
}

/**
 * Splits a pane: a new pane appears beside it (see `insertRelativeTo` for
 * the two placement cases) and immediately becomes the focused pane.
 *
 * @example
 * ```txt
 * one pane "a", split right with new pane "b":
 *
 *   ┌───────┐        ┌───┬───┐
 *   │   a   │   →    │ a │ b │      focus moves to b
 *   └───────┘        └───┴───┘
 * ```
 *
 * @param layout - The current layout document.
 * @param options - The target pane, direction, and new pane identity.
 * @returns The next document, or the same document when the target pane is
 * missing or the new id is already taken.
 */
function splitPane(
  layout: AppShellLayout,
  options: SplitPaneOptions,
): AppShellLayout {
  const { workspace } = layout
  const target = findNode(workspace.root, options.paneId)
  const wrapSplitId = options.newSplitId ?? `split:${options.newPaneId}`

  // Both new ids must be unused — a duplicate id would make every later
  // lookup, resize, and removal ambiguous.
  if (
    !target ||
    target.type !== "pane" ||
    findNode(workspace.root, options.newPaneId) ||
    findNode(workspace.root, wrapSplitId)
  ) {
    return layout
  }

  const newPane = createPaneNode({
    id: options.newPaneId,
    views: options.views,
    activeViewId: options.activeViewId,
  })

  const root = insertRelativeTo(
    workspace.root,
    options.paneId,
    newPane,
    options.direction,
    wrapSplitId,
  )

  return normalizeAppShellLayout({
    ...layout,
    workspace: {
      ...workspace,
      root,
      activePaneId: options.newPaneId,
      recentPaneIds: promoteRecentPane(
        workspace.recentPaneIds,
        options.newPaneId,
      ),
    },
  })
}

/**
 * Closes a pane. Its space goes back to the neighbor it was split from
 * (see `removeNode`), and focus moves to whichever surviving pane the user
 * touched most recently. The last remaining pane never closes.
 *
 * @param layout - The current layout document.
 * @param options - The pane to close.
 * @returns The next document, or the same document when the pane is missing
 * or is the last one.
 */
function closePane(
  layout: AppShellLayout,
  options: { paneId: LayoutNodeId },
): AppShellLayout {
  const { workspace } = layout
  const panes = collectPanes(workspace.root)

  if (panes.length <= 1 || !panes.some((pane) => pane.id === options.paneId)) {
    return layout
  }

  const { root } = removeNode(workspace.root, options.paneId)

  if (!root) {
    return layout
  }

  const { maximizedPaneId, ...rest } = workspace

  return normalizeAppShellLayout({
    ...layout,
    workspace: {
      ...rest,
      root,
      recentPaneIds: workspace.recentPaneIds.filter(
        (id) => id !== options.paneId,
      ),
      ...(maximizedPaneId !== undefined && maximizedPaneId !== options.paneId
        ? { maximizedPaneId }
        : {}),
    },
  })
}

/**
 * Focuses a pane, promoting it in the most-recently-active list.
 *
 * @param layout - The current layout document.
 * @param options - The pane to focus.
 * @returns The next document, or the same document when the pane is absent
 * or already active.
 */
function focusPane(
  layout: AppShellLayout,
  options: { paneId: LayoutNodeId },
): AppShellLayout {
  const { workspace } = layout

  if (workspace.activePaneId === options.paneId) {
    return layout
  }

  const target = findNode(workspace.root, options.paneId)

  if (!target || target.type !== "pane") {
    return layout
  }

  return {
    ...layout,
    workspace: {
      ...workspace,
      activePaneId: options.paneId,
      recentPaneIds: promoteRecentPane(workspace.recentPaneIds, options.paneId),
    },
  }
}

/**
 * Maximizes a pane over the workspace without restructuring the tree.
 *
 * @param layout - The current layout document.
 * @param options - The pane to maximize. Defaults to the active pane.
 * @returns The next document, or the same document when the pane is absent.
 */
function maximizePane(
  layout: AppShellLayout,
  options: { paneId?: LayoutNodeId } = {},
): AppShellLayout {
  const { workspace } = layout
  const paneId = options.paneId ?? workspace.activePaneId
  const target = findNode(workspace.root, paneId)

  if (!target || target.type !== "pane") {
    return layout
  }

  return focusPane(
    { ...layout, workspace: { ...workspace, maximizedPaneId: paneId } },
    { paneId },
  )
}

/**
 * Restores a maximized workspace to its split presentation.
 *
 * @param layout - The current layout document.
 * @returns The next document, or the same document when nothing is maximized.
 */
function restorePane(layout: AppShellLayout): AppShellLayout {
  if (layout.workspace.maximizedPaneId === undefined) {
    return layout
  }

  const { maximizedPaneId: _restored, ...workspace } = layout.workspace

  return { ...layout, workspace }
}

/**
 * Replaces the sibling sizes of one split, then repairs the document. The
 * weights can be in any scale — they are rescaled to sum to 1:
 *
 * @example
 * ```txt
 * weights [3, 1] → children sized [0.75, 0.25]
 * ```
 *
 * @param layout - The current layout document.
 * @param options - The split id and one weight per child, in child order.
 * @returns The next document, or the same document when the split is absent
 * or the weight count does not match its children.
 */
function setSplitWeights(
  layout: AppShellLayout,
  options: { splitId: LayoutNodeId; weights: readonly number[] },
): AppShellLayout {
  const { workspace } = layout

  /**
   * Rebuilds one subtree with the new weights applied.
   *
   * @param current - The subtree root being visited.
   * @returns The rebuilt subtree, or the same reference when untouched.
   */
  const visit = (current: LayoutNode): LayoutNode => {
    if (current.type === "pane") {
      return current
    }

    if (current.id === options.splitId) {
      if (options.weights.length !== current.children.length) {
        return current
      }

      return {
        ...current,
        children: current.children.map((child, index) => ({
          ...child,
          weight: options.weights[index],
        })),
      }
    }

    const children = current.children.map(visit)
    const unchanged = children.every(
      (child, index) => child === current.children[index],
    )

    return unchanged ? current : { ...current, children }
  }

  const root = visit(workspace.root)

  if (root === workspace.root) {
    return layout
  }

  return normalizeAppShellLayout({
    ...layout,
    workspace: { ...workspace, root },
  })
}

/**
 * Resets every split in the workspace to evenly distributed weights.
 *
 * @param layout - The current layout document.
 * @returns The normalized next document.
 */
function resetPaneSizes(layout: AppShellLayout): AppShellLayout {
  /**
   * Rebuilds one subtree with even weights.
   *
   * @param current - The subtree root being visited.
   * @returns The rebuilt subtree.
   */
  const visit = (current: LayoutNode): LayoutNode => {
    if (current.type === "pane") {
      return current
    }

    return {
      ...current,
      children: current.children.map((child) => ({
        ...visit(child),
        weight: formatWeight(1 / current.children.length),
      })),
    }
  }

  return normalizeAppShellLayout({
    ...layout,
    workspace: { ...layout.workspace, root: visit(layout.workspace.root) },
  })
}

/**
 * Opens or closes one dock. The dock's size is retained while closed.
 *
 * @param layout - The current layout document.
 * @param options - The dock side and requested visibility.
 * @returns The next document, or the same document when nothing changes.
 */
function setDockOpen(
  layout: AppShellLayout,
  options: { side: AppShellDockSide; open: boolean },
): AppShellLayout {
  const dock = layout.docks[options.side]

  if (dock.open === options.open) {
    return layout
  }

  return {
    ...layout,
    docks: { ...layout.docks, [options.side]: { ...dock, open: options.open } },
  }
}

/**
 * Reverses one dock's visibility.
 *
 * @param layout - The current layout document.
 * @param options - The dock side to toggle.
 * @returns The next document.
 */
function toggleDock(
  layout: AppShellLayout,
  options: { side: AppShellDockSide },
): AppShellLayout {
  return setDockOpen(layout, {
    side: options.side,
    open: !layout.docks[options.side].open,
  })
}

/**
 * Resizes one dock in pixels, clamped to optional bounds.
 *
 * @param layout - The current layout document.
 * @param options - The dock side, requested size, and optional bounds.
 * @returns The next document, or the same document when nothing changes.
 */
function resizeDock(
  layout: AppShellLayout,
  options: {
    side: AppShellDockSide
    size: number
    minSize?: number
    maxSize?: number
  },
): AppShellLayout {
  const dock = layout.docks[options.side]
  const size = Math.round(
    Math.min(
      options.maxSize ?? Number.MAX_SAFE_INTEGER,
      Math.max(options.minSize ?? 0, options.size),
    ),
  )

  if (!Number.isFinite(size) || dock.size === size) {
    return layout
  }

  return {
    ...layout,
    docks: { ...layout.docks, [options.side]: { ...dock, size } },
  }
}

